  values('ptd-minigame-focused-2026-10-09','Pelvic Trauma Decisions — focused edition with pre/post test','published','{"id":"ptd-minigame-focused-2026-10-09","title":"Pelvic Trauma Decisions — focused edition with pre/post test","governance":{"author":"Course content team","reviewer":null,"reviewDate":null,"status":"draft","supersedesVersion":"ptd-minigame-focused-2026-10-08"},"missions":[{"id":"mission-pre","number":4,"title":"Pre-test","entry":"Pre-test — 3 quick items before the cases. Answer from what you know now; there is no penalty and you will see your score at the end.","estimatedMinutes":3,"nodeIds":["PT1","PT2","PT3"],"contentVersion":"ptd-minigame-focused-2026-10-09"},{"id":"mission-1","number":1,"title":"The unstable patient","estimatedMinutes":6,"entry":"A 24-year-old motorcyclist arrives 35 minutes after injury. The airway is patent; pelvic pain and cool peripheries accompany HR 132/min and BP 82/50 mmHg. Your senior asks for the immediate concern.","nodeIds":["M1N1","M1N2","M1N3","M1N5","M1N4","M1N6"],"contentVersion":"ptd-minigame-focused-2026-10-09"},{"id":"mission-2","number":2,"title":"The apparently stable patient","estimatedMinutes":6,"entry":"A 40-year-old pedestrian is currently stable after assessment, with persistent posterior pelvic pain. A binder is documented as already in place on arrival and remains in place during this review. The case uses a textual AP report.","nodeIds":["M2N1","M2N2","M2N3","M2N4","M2N5"],"contentVersion":"ptd-minigame-focused-2026-10-09"},{"id":"mission-3","number":3,"title":"The hidden open injury","estimatedMinutes":6,"entry":"A 32-year-old man after a crush injury has a pelvic ring injury. Circulation has improved and remains monitored. During the continuing assessment, the team identifies a small perineal wound without visible bone.","nodeIds":["M3N1","M3N2","M3N3","M3N4"],"contentVersion":"ptd-minigame-focused-2026-10-09"},{"id":"mission-post","number":5,"title":"Post-test","entry":"Post-test — the same 3 sk